//! S6b：文本→像素的机制，加一条**冻结契约**让画面有确定的静止时刻。
//!
//! **为什么需要冻结契约**：图案只要被第二次写入，"可以取 PPM 的那一刻"就不存在了——
//! 宿主机一边取，内核一边滚，对账会莫名其妙地红。所以本模块带一个一次性闸门 [`FROZEN`]：
//! `freeze_band()` 一旦调用，之后所有写入都是 no-op。内核在冻结之后**必须**在串口上打
//! `fbcon: 已冻结 …`，宿主机以这行为准再 dump。契约的两端都是可测的：
//! 串口少了这一行 ⇒ 夹具等不到就绪；画面还在变 ⇒ 同一张 PPM 两次采样不一致。
//!
//! **字形是一份资产，不是一个公式**（S6e / ADR-086）：S6b 时期字形由码点的一个算术公式算出，
//! 结果 95 个可打印 ASCII 只落在 **5 种** 8×8 图样上（每格约 2.3 bit）——画面"画得出"但**读不出**。
//! 现在 ASCII 与宽字符各有一份位图资产（`kernel/assets/font8x16.hex`、`font16x16.hex`），
//! 表由资产生成，"可读"因此可以变成可复算的判据（图样两两不同、覆盖集里每个字都有字形、
//! 以及宿主机把真实画面**读回文本**与串口逐字比对）。
//!
//! **S6f：双宽格**。ASCII 一列一格、非 ASCII 两列一格；宽字符的覆盖集是
//! **内核字符串字面量里出现过的全部非 ASCII 字符**（实测 532 个，见 [`WIDE_CP`]）。
//! 表外的宽字符画**空心框**——它必须看起来"这里有个字但我没有它的形状"，
//! 而不是变成 `?`（那会让缺失看起来像内容）。
//!
//! 本文件零 `unsafe`：所有像素写入都走 [`crate::frame::Frame::put`]，越界由它判。

use alloc::string::String;

use crate::frame::Frame;
use core::sync::atomic::{AtomicBool, Ordering};

/// 点阵放大倍率。**S6h 起是 1**：字形直接按目标尺寸栅格化（ASCII 26 px、宽字 28 px），
/// 不再把 14 px 放大成 2×2 块——块状放大会把笔画撑到 4 px、吃掉字内留白，
/// 屏幕上是"糊、像缺笔画"（用户截图驱动，BACKLOG §251）。
pub const SCALE: u64 = 1;

/// 2 bit 灰阶（0..3）→ 与底色混合。界面字体只有 4 级，够出边缘过渡，
/// 又不至于让"读出字形"依赖一张大表。
fn mix(fg: u32, bg: u32, a: u32) -> u32 {
    let ch = |sh: u32| -> u32 {
        let f = (fg >> sh) & 0xFF;
        let b = (bg >> sh) & 0xFF;
        (b as i32 + (f as i32 - b as i32) * a as i32 / 3) as u32
    };
    (ch(16) << 16) | (ch(8) << 8) | ch(0)
}
